uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;
uniform float u_neon_glow;
uniform float u_bloom;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Distance to a line segment
float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

void main() {
    // 1. UV Setup
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 mouse = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) * 2.0 : vec2(0.0);

    // 2. Safely Extract Parameters
    float spd = (u_speed <= 0.0) ? 1.0 : u_speed;
    float t = iTime * 0.15 * spd; // Smooth, elegant pacing

    float layers = clamp(u_layers <= 0.0 ? 4.0 : u_layers, 1.0, 6.0);
    float scale = (u_scale <= 0.0) ? 1.0 : u_scale;
    float density = (u_density <= 0.0) ? 1.0 : u_density;

    // Connection Radius repurposed for Fluid Warping Strength
    float warpStrength = (u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 0.5;

    float intensity = (u_intensity <= 0.0) ? 1.5 : u_intensity;
    float neonGlow = (u_neon_glow <= 0.0) ? 1.5 : u_neon_glow;
    float pulseInt = (u_pulse_intensity <= 0.0) ? 1.5 : u_pulse_intensity;
    float bloom = (u_bloom <= 0.0) ? 1.0 : u_bloom;

    // 3. Vibrant Cyber Colors
    float hueBase = fract((u_color_base <= 0.0 ? 0.6 : u_color_base) + t * u_color_cycle * 0.2);
    float huePulse = fract((u_color_pulse <= 0.0 ? 0.8 : u_color_pulse) + t * u_color_cycle * 0.2);

    // Deeply saturated, rich light
    vec3 cBase = hsv2rgb(vec3(hueBase, 0.9, 1.0));
    vec3 cPulse = hsv2rgb(vec3(huePulse, 0.8, 1.0));

    // START WITH PURE BLACK (Guarantees infinite contrast, no "screen of color")
    vec3 finalCol = vec3(0.0);

    // 4. Parallax Rendering Loop (Painter's Algorithm: Back to Front)
    for(float i = layers; i > 0.0; i -= 1.0) {

        // Z-depth calculates distance from camera. Loops from 0.0 to 1.0 continuously.
        float z = fract(i / layers - t * 0.5); 

        // Fade layers in at the back (z=1) and out at the camera (z=0)
        float fade = smoothstep(0.0, 0.1, z) * smoothstep(1.0, 0.8, z);

        // Scale space based on depth to create infinite 3D zoom
        float depthScale = mix(12.0, 1.5, z) * scale * density;
        vec2 luv = uv * depthScale;

        // Mouse Parallax for interactive 3D feel
        luv += mouse * (1.0 - z) * 3.0;

        // Rotate each layer slightly to break up grid patterns
        luv *= rot(z * 0.5 + i);

        // --- FLUID DOMAIN WARPING ---
        // This is the secret. It takes rigid straight grids and mathematically bends 
        // them so the connections curve and flow like organic silk or underwater plants.
        luv.x += sin(luv.y * 0.6 + t * 2.0) * warpStrength;
        luv.y += cos(luv.x * 0.6 - t * 1.5) * warpStrength;

        vec2 id = floor(luv);
        vec2 f = fract(luv);

        // Layer Alpha accumulators
        vec3 layerRGB = vec3(0.0);
        float layerAlpha = 0.0;

        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));
                vec2 nId = id + offs;

                // Organic wandering movement for the nodes
                vec2 p1 = offs + 0.5 + 0.35 * sin(t * 3.0 + hash22(nId) * 6.28);

                // --- DRAW NODE (Glowing Neural Core) ---
                float dNode = length(f - p1);
                float nCore = smoothstep(0.08, 0.02, dNode); // Thick, solid center
                float nGlow = exp(-dNode * 12.0) * neonGlow; // Wide, soft ambient halo

                layerRGB += mix(cBase, vec3(1.0), nCore) * (nCore + nGlow);
                layerAlpha += nCore + nGlow * 0.5;

                // --- DRAW CONNECTIONS (Bioluminescent Tendrils) ---
                // We only look Right, Down, and Diagonal to prevent drawing lines twice
                vec2[] dirs = vec2[](vec2(1,0), vec2(0,1), vec2(1,1), vec2(-1,1));
                for(int d = 0; d < 4; d++) {
                    vec2 dir = dirs[d];
                    vec2 tId = nId + dir;
                    vec2 p2 = offs + dir + 0.5 + 0.35 * sin(t * 3.0 + hash22(tId) * 6.28);

                    float dConn = distance(p1, p2);

                    if(dConn < 1.6) { 
                        float dLine = distLine(f, p1, p2);

                        // Lush, thick neon lines
                        float lCore = smoothstep(0.04, 0.01, dLine);
                        float lGlow = exp(-dLine * 15.0) * neonGlow;

                        // Animated Data Pulses
                        float pulseTime = t * 8.0 + hash21(nId) * 10.0;
                        float pulse = smoothstep(0.8, 1.0, sin(dConn * 5.0 - pulseTime));
                        pulse *= smoothstep(1.6, 0.8, dConn); // Organic fade-out for long lines

                        // Mix base color with pulse color
                        vec3 lineCol = mix(cBase, cPulse, pulse * pulseInt);

                        // Accumulate Color and Alpha independently
                        layerRGB += lineCol * lCore;
                        layerRGB += lineCol * lGlow * (0.4 + pulse * 0.6);
                        layerAlpha += lCore + lGlow * 0.4;
                    }
                }
            }
        }

        // --- PURE ALPHA COMPOSITING ---
        // This clamps the layer so it can NEVER blow out to white fog.
        // It stamps the glowing web cleanly onto the black background.
        layerAlpha = clamp(layerAlpha, 0.0, 1.0);
        finalCol = mix(finalCol, layerRGB * intensity, layerAlpha * fade);
    }

    // 5. Lush Post-Processing
    // Cinematic Center Bloom (Subtle glow rising from the deep)
    finalCol += cBase * bloom * exp(-length(uv) * 3.0) * 0.3;

    // Rich Vignette framing to push focus to the center
    float vig = smoothstep(1.4, 0.1, length(uv));
    finalCol *= vig;

    // ACES-style Tone Mapping (Hollywood standard for handling neon colors without washing out to white)
    finalCol = (finalCol * (2.51 * finalCol + 0.03)) / (finalCol * (2.43 * finalCol + 0.59) + 0.14);

    fragColor = vec4(finalCol, 1.0);
}
